import { FC } from 'react';

interface DatePickerProps {
    /** 是否打开 */
    open: boolean;
    /** 当前值 */
    value?: Date;
    /** 默认值 */
    defaultValue?: Date;
    /** 最小日期 */
    min?: Date;
    /** 最大日期 */
    max?: Date;
    /** 精度 */
    precision?: 'year' | 'month' | 'day';
    /** 标题 */
    title?: string;
    /** 确认回调 */
    onConfirm?: (value: Date) => void;
    /** 取消回调 */
    onCancel?: () => void;
    /** 关闭回调 */
    onClose?: () => void;
}

declare const DatePicker: FC<DatePickerProps>;

export { DatePicker, DatePicker as default };
export type { DatePickerProps };
